package com.drogaria.backend.dto;
import jakarta.validation.constraints.Email; import jakarta.validation.constraints.NotBlank;
public class ClienteUpdateRequest { @NotBlank private String nome; @NotBlank @Email private String email; private String telefone; public String getNome(){return nome;} public void setNome(String v){nome=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getTelefone(){return telefone;} public void setTelefone(String v){telefone=v;} }